test('localLink handles subscriptions with tracked envelopes and observables', async () => {
  const t = initTRPC.create();

  const router = t.router({
    onTracked: t.procedure.subscription(async function* () {
      yield tracked('1', 'first');
      yield tracked('2', 'second');
    }),
    onObservable: t.procedure.subscription(() => {
      return observable<string>((emit) => {
        emit.next('obs-1');
        emit.next('obs-2');
        emit.complete();
      });
    }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const trackedEvents: Array<{ id: string; data: string }> = [];
  await new Promise<void>((resolve, reject) => {
    client.onTracked.subscribe(undefined, {
      onData(data) {
        trackedEvents.push(data);
      },
      onComplete() {
        resolve();
      },
      onError(err) {
        reject(err);
      },
    });
  });

  expect(trackedEvents).toEqual([
    { id: '1', data: 'first' },
    { id: '2', data: 'second' },
  ]);

  const obsEvents: string[] = [];
  await new Promise<void>((resolve, reject) => {
    client.onObservable.subscribe(undefined, {
      onData(data) {
        obsEvents.push(data);
      },
      onComplete() {
        resolve();
      },
      onError(err) {
        reject(err);
      },
    });
  });

  expect(obsEvents).toEqual(['obs-1', 'obs-2']);
});
